body:
Closes #17 

This PR extends the ioda-stats utility to also optionally write out regular binned statistics to a gridded variable in the netCDF output file.

For example:
```
time window:
  begin: 2021-12-20T21:00:00Z
  length: PT6H
  bound to include: begin
obs spaces:
- obs space:
    name: ims_snow
    obsdatain:
      engine:
        type: H5File
        obsfile: ./diag_ims_snow_2021122100.nc
    simulated variables: ['totalSnowDepth']
    observed variables: ['totalSnowDepth']
  variables: ['totalSnowDepth']
  groups to process: ['ombg', 'oman']
  qc groups: ['EffectiveQC0', 'EffectiveQC1']
  statistics to compute: ['mean', 'count', 'RMS']
  output file: output_ims_snow.nc
  regular grid binning:
    bin size in degrees: 1.0
    vertical bins:
    - vertical bin:
        name: all
        mask variable: stationElevation
        mask range: [0, 1000000]
    - vertical bin:
        name: none
        mask variable: stationElevation
        mask range: [0, 1]
  domains to process:
  - domain:
      name: "NH"
      first mask variable: latitude
      first mask range: [0,90]
```
will produce a file like this:
```
netcdf output_ims_snow {
dimensions:
	analysisCycle = UNLIMITED ; // (1 currently)
	Domain = 2 ;
	binsZDim = 2 ;
	binsYDim = 180 ;
	binsXDim = 360 ;
variables:
	string validTime(analysisCycle) ;
	string statisticDomain(Domain) ;
	string verticalBin(binsZDim) ;

group: byDomains {

  group: ombg {

    group: totalSnowDepth {
      variables:
      	float mean(analysisCycle, Domain) ;
      	int count(analysisCycle, Domain) ;
      	float RMS(analysisCycle, Domain) ;
      } // group totalSnowDepth
    } // group ombg

  group: oman {

    group: totalSnowDepth {
      variables:
      	float mean(analysisCycle, Domain) ;
      	int count(analysisCycle, Domain) ;
      	float RMS(analysisCycle, Domain) ;
      } // group totalSnowDepth
    } // group oman
  } // group byDomains

group: griddedBins {

  group: ombg {

    group: totalSnowDepth {
      variables:
      	float mean(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      	int count(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      	float RMS(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      } // group totalSnowDepth
    } // group ombg

  group: oman {

    group: totalSnowDepth {
      variables:
      	float mean(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      	int count(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      	float RMS(analysisCycle, binsZDim, binsYDim, binsXDim) ;
      } // group totalSnowDepth
    } // group oman
  } // group griddedBins
}
```
